const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function publicPage(route, supportUrl) {
  let support = 'https://github.com/akhan157/plainhand/issues';
  try { const url = new URL(supportUrl); if (url.protocol === 'https:' && !url.username && !url.password) support = url.href; } catch {}
  const pages = {
    '/privacy': ['Privacy', `<p>Plainhand stores your sign-in email, profile, resume, saved roles, drafts, generated files, application records, connected-app grants and help requests in its hosted Postgres workspace and Supabase Auth. Sessions use secure cookies; workspace access requires your account.</p><p>Your connected AI chat can read workspace context and save drafts through tools you authorize. Its provider handles that context under its own terms. Review connector permissions before connecting. Plainhand does not claim audited compliance.</p><p><strong>Browser extension.</strong> The Plainhand extension reads a page only when you click one of its buttons on that page. <em>Save this job</em> sends the page address, company, role and posting text to your workspace. <em>Fill this page</em> sends the page address and the form's field labels and choices, fills fields with answers from your approved application, and attaches your approved resume and cover letter files. Sensitive questions are left for you, and it never submits an application. It keeps its Plainhand sign-in in your browser's extension storage. It does not read your browsing history, does not run on pages you have not clicked it on, and does not sell or share data or use it for advertising. Plainhand's use of information received through the extension adheres to the Chrome Web Store User Data Policy, including the Limited Use requirements.</p><p>Use workspace export in Settings for your saved state, or download individual packet files. Delete your account to remove live workspace records, sessions and grants and request deletion of the Supabase Auth user. Copies already exported or shared with an AI provider remain with those recipients.</p><p>Saved workspace data and help requests remain until account deletion or removal. Sessions expire after 30 days; expired session and rate-limit records are purged daily. When encrypted operational backups are enabled, copies are scheduled to expire after 14 days; deletion is not immediate in backups. Backups must be configured by the operator before launch.</p>`],
    '/terms': ['Terms', `<p>Plainhand is a job-search drafting and organization tool provided under the project's MIT license, without a guarantee of availability, accuracy, interviews or employment. You are responsible for the facts and materials you share and for respecting employer and AI-provider rules.</p><p>Review every generated claim, answer and file. Approval prepares a packet; it does not submit an application. The candidate performs the final submission on the employer's page. Never use Plainhand to fabricate experience, impersonate another person or send abusive applications.</p><p>AI subscriptions and connector availability are controlled by their providers. Automated daily job checks are pending; the daily maintenance job only checks database connectivity and purges expired sessions and rate limits.</p>`],
    '/support': ['Support', `<p>Signed-in users can use Get help to save a message, screen name and request error IDs for follow-up. It does not automatically attach workspace contents. Do not include resumes, passwords, tokens or sensitive personal data in help messages or public issues.</p><p>When a server request fails, copy the errorId in the response or X-Request-ID header. Server logs contain only that identifier, HTTP method and status. External error tracking is not enabled; a Sentry DSN alone does not activate it.</p><p><a href="${esc(support)}">Project support channel</a>. Public issues are visible to everyone. Help requests are saved in your account; no response time or live support is promised. For security reports, follow <a href="https://github.com/akhan157/plainhand/security/policy">the security policy</a>.</p>`],
  };
  const [title, body] = pages[route];
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${title} · Plainhand</title><link rel="stylesheet" href="/auth.css"></head><body><main><h1>${title}</h1>${body}<nav aria-label="Information"><a href="/signin">Sign in</a> · <a href="/privacy">Privacy</a> · <a href="/terms">Terms</a> · <a href="/support">Support</a></nav></main></body></html>`;
}
